typedef unsigned int size_t;

class color32 {
public:
    unsigned int value;
    color32(unsigned int v = 0) : value(v) {}
};

class stringx {
    char data[8];
public:
    stringx(const stringx&);
    ~stringx();
};

class Font;
class FEMenuSystem;
class FEMenuEntry;

void *operator new(size_t, unsigned int, const char *, int);

class FEMenu {
    char data[112];
public:
    virtual ~FEMenu();
    FEMenu();
    void cons(FEMenuSystem *, int, int, color32, color32, color32,
              float = 1.0f, float = 1.2f, int = 8, int = 0);
    void Add(FEMenuEntry *);
    void SetHelpText(int);
};

class FEMenuEntry {
public:
    virtual ~FEMenuEntry();
    int entry_num;
    FEMenuEntry *next;
    FEMenuEntry *previous;
    FEMenu *menu;
    bool highlight;
    bool disabled;
    char padding0[2];
    void *ent;
    color32 high_ent_color;
    color32 norm_ent_color;
    void *text;
    float highlight_intensity;
    float highlight_timer;
    int disabled_alpha;
    color32 special_color;
    color32 special_color_high;
    bool has_special_color;
    bool no_flash;
    char padding1[2];
    float special_scale;
    float special_scale_high;
    bool has_special_scale;
    char padding2[3];
    FEMenuEntry *up;
    FEMenuEntry *down;
    FEMenuEntry *left;
    FEMenuEntry *right;

    FEMenuEntry(stringx name, FEMenu *menu, bool disabled = false,
                Font *font = 0)
        : high_ent_color(), norm_ent_color(), special_color(),
          special_color_high()
    {
        cons(name, menu, disabled, font);
    }

    void cons(stringx, FEMenu *, bool, Font *);
};

class PauseMenuSystem;

class OptionsMenuClass : public FEMenu {
public:
    PauseMenuSystem *sys;
    FEMenuEntry *sound;
    FEMenuEntry *display;
    FEMenuEntry *rumble;

    OptionsMenuClass(FEMenuSystem *, int, int, color32, color32, color32);
};

extern stringx menu_sound;
extern stringx menu_handicap;
extern stringx menu_camera;
extern stringx menu_display;
extern stringx menu_rumble;
extern const char frontend_menus_cpp[];

__asm__(".equ menu_sound,0x003E6078");
__asm__(".equ menu_handicap,0x003E6058");
__asm__(".equ menu_camera,0x003E6080");
__asm__(".equ menu_display,0x003E6180");
__asm__(".equ menu_rumble,0x003E6200");
__asm__(".equ frontend_menus_cpp,0x004C2FB8");

OptionsMenuClass::OptionsMenuClass(
    FEMenuSystem *s, int x, int y, color32 c, color32 hc, color32 hca)
{
    cons(s, x, y, c, hc, hca, 1.0f, 1.2f, 8, 0);
    sys = (PauseMenuSystem *)s;
    Add(sound = new (0, frontend_menus_cpp, 0)
        FEMenuEntry(menu_sound, this));
    Add(new (0, frontend_menus_cpp, 0)
        FEMenuEntry(menu_handicap, this));
    Add(new (0, frontend_menus_cpp, 0)
        FEMenuEntry(menu_camera, this));
    Add(display = new (0, frontend_menus_cpp, 0)
        FEMenuEntry(menu_display, this));
    Add(rumble = new (0, frontend_menus_cpp, 0)
        FEMenuEntry(menu_rumble, this));
    *(float *)((char *)this + 52) = 1.0f;
    SetHelpText(115);
    *(int *)((char *)this + 60) |= 0x402;
}
